pub const Tag = lang.Tag;

/// Roles exist only in schema mode.
pub const Role = enum(u16) {};

/// Start symbols; `BaseParser.parse(start)` parses one.
pub const Start = enum(u16) {
    @"program" = 3,
    @"expr" = 4,
};

