};
const expectedOf = [_]u16{
    0, 0, 1, 1, 2, 3, 4, 5, 2, 2, 6, 2, 1, 7, 2, 5, 7, 8, 1, 1, 9, 1, 1, 10,
    7, 7, 10, 10, 11, 3, 12, 5, 12, 4, 4, 2, 2, 10, 1, 11, 10,
};

fn expectedIn(state: u16) []const u16 {
    const i = expectedOf[state];
    return expectedSymbols[expectedOffsets[i]..expectedOffsets[i + 1]];
}

fn symbolName(sym: u16) []const u8 {
    return switch (sym) {
        1 => "end of input",
        9 => "newline",
        10 => "\"=\"",
        12 => "\"(\"",
        13 => "\")\"",
        14 => "\",\"",
        17 => "ident",
        18 => "integer",
        19 => "string_dq",
        26 => "\"+\"",
        27 => "\"-\"",
        28 => "\"*\"",
        else => "",
    };
}

